1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	};
12	
13	/** Initial assessment surcharge on a customer's first insurance. */
14	const FIRST_INSURANCE_RATE = 0.1;
15	
16	export type Scenario = {
17	  customer: { yearsWithMHPCO: number };
18	  steps: Step[];
19	};
20	
21	export type Step = {
22	  op: string;
23	  items: Item[];
24	};
25	
26	export type Item = { type: string } & Record<string, unknown>;
27	
28	export type Result = { premium: number };
29	
30	export type ScenarioOutcome = { results: Result[] };
31	
32	/** Sum of the base premiums of every item on a policy. */
33	const calculateBasePremium = (items: Item[]): number =>
34	  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
35	
36	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
37	  const quotedItems = scenario.steps[0].items;
38	  const policyBasePremium = calculateBasePremium(quotedItems);
39	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
40	  return {
41	    results: [
42	      {
43	        premium: Math.ceil(
44	          policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
45	        ),
46	      },
47	    ],
48	  };
49	};
