/** Sum of the base premiums of every item on a policy. */
const calculateBasePremium = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);

/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
const roundPremium = (amount: number): number => Math.ceil(amount);

/** Price a policy covering the given items. */
const quotePremium = (items: Item[]): number => {
  const policyBasePremium = calculateBasePremium(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
  return roundPremium(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

